 ldr:{title:'Bir ışık ölçer',intro:'LDR direnci ışıkla değişir. 10 kΩ dirençle bir gerilim bölücü oluşturur. analogRead() ile ölçtüğün değeri yüzdeye dönüştür.',steps:['Başlangıç kodunu çalıştır ve Kontroller çubuğundaki ışık sürgüsünü hareket ettir. Ham değerleri izle.','Ölçümü dönüştür: `int percent = map(raw, 0, 4095, 0, 100);`','`Light: 42 %` biçiminde yazdırmak için `Serial.print()` kullan; son parçayı `Serial.println()` ile bitir.'],hints:['Daha fazla ışık daha yüksek değer üretir: LDR direnci düşer ve bölücü gerilimi 3,3 V yönüne gider.','Önce etiketi, sonra sayıyı, sonra birimi yazdır: `Serial.print("Light: ");`'],goals:['Monitörde Light: … % görünüyor','Karanlık: %30 altında','Aydınlık: %70 üzerinde']},
 nightlight:{title:'Bir gece lambası',intro:'Oda karardığında LED kendiliğinden yansın.',steps:['Başlangıç kodunu çalıştır ve ışık sürgüsünü oynat: LED henüz tepki vermez.','`raw` ile `DARK_LIMIT` değerini `if` / `else` içinde karşılaştır.','Karanlıkta LED’i yak, aydınlıkta söndür.'],hints:['Karanlıkta ölçüm küçülür; koşul `raw < DARK_LIMIT` olmalı.','`if` içinde `digitalWrite(LED_PIN, HIGH);`, `else` içinde `LOW` kullan.'],goals:['Aydınlıkta LED sönük','Karanlıkta LED yanıyor']},
 melody:{title:'Bir melodi çal',intro:'Pasif buzzer, hertz (Hz) cinsinden frekans verdiğinde nota çalar. tone(pin, frequency, duration) hemen döner; notalar arasına delay() ekle.',steps:['Başlangıç kodunu çalıştır: do notasını duyarsın.','Re notasını ekle: `tone(BUZZER_PIN, 294, 300);` ardından `delay(400);`','Arkasına mi notasını (330 Hz) ekle. Çalıştır ve do, re, mi dizisini dinle.'],hints:['Süre (300 ms) notanın uzunluğu, delay(400) ise sonraki çağrıya kadar geçen zamandır.','Frekans yükseldikçe ses incelir. Do, re, mi: 262, 294 ve 330 Hz.'],goals:['Do çalıyor (262 Hz)','Ardından re (294 Hz)','Ardından mi (330 Hz)']},
 alarm:{title:'Görev: kutu alarmı',intro:'LDR kapalı bir kutunun içinde. Kapak açılıp ışık girince buzzer çalmalı, kutu kapanınca susmalı.',steps:['`raw` ile `OPEN_LIMIT` değerini karşılaştır.','Sınırın üstündeyken `tone(BUZZER_PIN, 880);` çağır.','Diğer durumda buzzer’ı susturmak için `noTone(BUZZER_PIN);` çağır.'],hints:['Süre verilmezse tone(), noTone() çağrılana kadar çalar.','Kapalı kutu = karanlık = küçük ölçüm.'],goals:['Kutu kapalı (karanlık): sessiz','Kutu açık (aydınlık): buzzer çalıyor']},
 temp:{title:'Bir termometre',intro:'DHT11 sıcaklık ve nemi tek veri kablosuyla gönderir. Hassas zamanlamayı DHT kütüphanesi yapar.',steps:['Başlangıç kodunu çalıştır ve Kontroller çubuğundan sıcaklığı değiştir.','Nemi oku: `float h = dht.readHumidity();`','`Temp: 24.0 C  Humidity: 50 %` biçiminde tek satır yazdır. Başarısız ölçümü `isnan()` ile yakala.'],hints:['`Serial.print(t, 1);` ondalık noktadan sonra bir basamak yazar.','DHT11 yavaştır; yaklaşık iki saniyede bir yeni ölçüm verir.'],goals:['Monitörde Temp: … C  Humidity: … % görünüyor','Sıcak oda (30 derece, %70) doğru raporlanıyor']},
 oled:{title:'OLED’e merhaba de',intro:'OLED, I²C ile bağlanır: SDA ve SCL. Önce bellek tamponuna çiz, sonra display.display() ile ekrana gönder.',steps:['Başlangıç kodunu çalıştır: çizim gönderilmediği için ekran siyah kalır.','İlk satırın altına ikinci satırı ekle: `display.println("ESP32");`','setup() sonunda `display.display();` ile tamponu ekrana gönder.'],hints:['display.display() öncesindeki işlemler yalnızca bellekteki tamponu değiştirir.','İlk println() imleci sonraki satıra taşır; ikinci metin altında görünür.'],goals:['Ekranda içerik var','İlk satır Hello! diyor','Altında ikinci satır görünüyor']},
 station:{title:'Küçük bir hava istasyonu',intro:'İki parçayı birleştir: DHT11 ölçer, OLED gösterir. Bağlantılar hazır. Ekranın ikinci satırını tamamla.',steps:['Başlangıç kodunu çalıştır: yalnızca sıcaklık görünüyor.','Sıcaklık satırının ardından `display.print("H: ");` ekle.','Nemi `display.print(h, 0);` ile yazdır; satırı `display.println(" %");` ile bitir.'],hints:['print() aynı satıra ekler; println() satırı bitirir.','Sıcaklık sürgüsünü değiştir ve iki saniye bekle: ekran takip eder.'],goals:['Sıcaklık ekranda','Nem ekranda','Sensörü takip ediyor: 30 derece']},
